agent_sql:
/* 1. How many distinct years are present in the data */
WITH total_years AS (
    SELECT COUNT(DISTINCT "YEAR") AS yr_cnt
    FROM crime_incidents
),

/* 2. For each district, count the distinct years it appears in */
district_years AS (
    SELECT "DISTRICT"               AS district,
           COUNT(DISTINCT "YEAR")   AS yr_cnt
    FROM   crime_incidents
    GROUP  BY "DISTRICT"
)

/* 3. Keep only districts whose year‑count matches the total number of years,
      then count those districts */
SELECT COUNT(*) AS districts_with_crime_every_year
FROM   district_years dy
JOIN   total_years   ty
       ON dy.yr_cnt = ty.yr_cnt;

/* 1. How many distinct years are present in the data */
WITH total_years AS (
    SELECT COUNT(DISTINCT "YEAR") AS yr_cnt
    FROM crime_incidents
),

/* 2. For each district, count the distinct years it appears in */
district_years AS (
    SELECT "DISTRICT"               AS district_id,
           COUNT(DISTINCT "YEAR")   AS yr_cnt
    FROM crime_incidents
    GROUP BY "DISTRICT"
)

/* 3. Keep only those districts whose year‑count matches the total number of years,
      then count those districts */
SELECT COUNT(*) AS districts_with_crime_in_every_year
FROM district_years dy
JOIN total_years ty
      ON dy.yr_cnt = ty.yr_cnt;

/*  Count the districts that have reported at least one crime in every year  */
SELECT COUNT(*) AS districts_with_crime_in_all_years
FROM (
        SELECT ci."DISTRICT"
        FROM   crime_incidents ci
        GROUP  BY ci."DISTRICT"
        HAVING COUNT(DISTINCT ci."YEAR") = (
                 SELECT COUNT(DISTINCT "YEAR")
                 FROM   crime_incidents
               )
     ) AS d;

